/**
 * Top-level planner entry — fixed-point loop per `04-` §16.
 *
 * Pure function `plan_unmemoized(snapshot, rootTaskId?, inclusive?): PlanResult`.
 *
 * Algorithm:
 *   1. Build SchedulingGraph (memoized in core/api.ts).
 *   2. Cycle short-circuit (Part I §5 — no partial plans): findCycles on the
 *      graph; if any, return PlanResult{ conflicts:[{kind:"cycle",...}],
 *      plans: empty, iterations:0, converged:true, order:[] }.
 *   3. selectComponent(graph, rootTaskId, inclusive) when rootTaskId given;
 *      else the full graph is in scope.
 *   4. plan_0 — initial PlanState built from anchor dates.
 *   5. For i in 1..maxIterations:
 *        plan_i = scheduleOnce(graph, plan_{i-1}, config, scope)
 *        if plansEqual(plan_i, plan_{i-1}) → converged.
 *   6. PlanResult emits only entries that differ from the snapshot's task
 *      dates (sparse output per `04-` §A.7) and includes the toposort
 *      `order` so the adapter can fire `onAfterTaskAutoSchedule` in the
 *      planner's resolution order.
 */

import type {
  Conflict,
  NormalizedTaskID,
  PlanResult,
  ScheduledDates,
  ScheduleReason,
  Snapshot,
  TaskID
} from "../types";
import type { SchedulingGraph } from "../graph/types";
import { normalizeTaskId, toTaskEndpointReason } from "../ids";
import { buildSchedulingGraph, findCycles } from "../api";
import { scheduleOnce, type PerNodePlan, type PlanState } from "./schedule_pass";
import { selectComponent, selectPredecessorClosure } from "./connected";
import { resolveConstraintType } from "./constraints";

/** Shared empty map for the iterations before the block has a shift. */
const NO_RAISED_ANCHORS: ReadonlyMap<NormalizedTaskID, { startTs: number; endTs: number }> =
  new Map();

/**
 * The GS-3596 project-shape anchor nodes that a moved block DRIVES.
 *
 * `buildProjectShapeRelations` models a project's internal layout as
 * `tethered leaf -> anchor -> receiving sibling`, with the offsets on both legs
 * re-derived from the leaves' live starts. The anchor is a scheduling node but
 * not a snapshot task, so a set of block leaf ids cannot recognise it - and it
 * is emphatically not something that stays put: it follows a tethered leaf that
 * the drag moved. `schedule_pass` needs to know which anchors those are, both to
 * keep them out of the block's shortfall and to stop their outbound edge
 * positioning the block's other leaves; the reasoning is at the two use sites
 * (round-4 finding R4-M1).
 *
 * "Not in `snapshot.tasks`" is the synthetic test - the anchor ids are reserved
 * against every task in the snapshot precisely so no real task can answer to one
 * (`project_shape_edges.ts`, `uniqueAnchorId`). "Every inbound edge from a block
 * leaf" is the driven test, and it is deliberately ALL rather than ANY: an
 * anchor a leaf outside the block also feeds carries something that stays put,
 * so it stays external. Walking the block's successors rather than the whole
 * node map keeps this proportional to the block, and it runs only inside the
 * moved-project cell.
 */
function blockShapeAnchors(
  snapshot: Snapshot,
  graph: SchedulingGraph,
  blockLeafIds: ReadonlySet<NormalizedTaskID>
): ReadonlySet<NormalizedTaskID> {
  const anchors = new Set<NormalizedTaskID>();
  for (const leafId of blockLeafIds) {
    for (const out of graph.successors.get(leafId) ?? []) {
      const candidate = out.target;
      if (anchors.has(candidate)) continue;
      if (snapshot.tasks.has(candidate)) continue;
      const inbound = graph.predecessors.get(candidate) ?? [];
      if (inbound.length === 0) continue;
      let driven = true;
      for (const e of inbound) {
        if (!blockLeafIds.has(e.source)) { driven = false; break; }
      }
      if (driven) anchors.add(candidate);
    }
  }
  return anchors;
}

export function plan_unmemoized(
  snapshot: Snapshot,
  rootTaskId?: TaskID,
  inclusive: boolean = true
): PlanResult {
  const graph = buildSchedulingGraph(snapshot);

  // Part I §5: short-circuit on cycles. Engine emits no partial plan.
  const cycles = findCycles(graph);
  if (cycles.length > 0) {
    const conflicts: Conflict[] = cycles.map(c => ({
      kind: "cycle" as const,
      taskIds: c.tasks,
      linkIds: c.links
    }));
    return {
      plans: new Map(),
      iterations: 0,
      converged: true,
      conflicts,
      order: []
    };
  }

  // Optional component scoping per D-02.
  //
  // When `rootTaskId` is a SUMMARY task that's been filtered from the
  // scheduling graph (e.g., `gap_behavior:"compress"` collapses moveProjects
  // to false, so every summary is dropped from `graph.nodes`), the bare
  // `selectComponent(graph, summaryId, ...)` returns an empty scope and
  // the planner does nothing. v1's `linksBuilder.getLinkedTasks(summaryId,
  // true)` walks both the summary's `$source`/`$target` links AND iterates
  // its children, collecting every linked task in the subtree. Mirror that
  // by treating the summary's descendants as additional roots — union the
  // scope of every in-graph descendant.
  //
  // Test 11_auto_scheduling/017_finish_to_start.js exercises this:
  // `gantt.addLink({source: 1, target: 2})` triggers
  // `autoScheduleViaEngine(gantt, 1, true)` where task 1 is a project
  // summary; under compress the link expands to leaf-to-leaf edges, so the
  // planner has work to do — but only if the leaves are in scope.
  let scope: ReadonlySet<NormalizedTaskID> | undefined;
  let normalizedRootTaskId: NormalizedTaskID | undefined;
  // The nodes that stand for the root when the pass asks "did the user put this
  // where it is?" — see `PassInputs.rootAnchorIds`. The root's own id always
  // qualifies; the filtered-summary branch below adds the descendants that get
  // rescheduled in its place.
  let rootAnchorIds: ReadonlySet<NormalizedTaskID> | undefined;
  // Set only for a moved summary root - see `PassInputs.movedBlock` and the
  // `blockShift` loop below.
  let block: {
    leafIds: ReadonlySet<NormalizedTaskID>;
    /** GS-3596 shape anchors the block drives - see where it is built. */
    anchorIds: ReadonlySet<NormalizedTaskID>;
    baseAnchors: ReadonlyMap<NormalizedTaskID, { startTs: number; endTs: number }>;
    /** Milliseconds. See the note at the collection site for why not working time. */
    maxShift: number;
  } | undefined;
  if (rootTaskId !== undefined) {
    normalizedRootTaskId = normalizeTaskId(rootTaskId);
    const anchorIds = new Set<NormalizedTaskID>([normalizedRootTaskId]);
    rootAnchorIds = anchorIds;
    // GS-3596: the scheduling graph also holds internal shape-anchor nodes,
    // which stand for a project's layout rather than for a task.
    // `buildProjectShapeRelations` keeps their ids clear of every task the
    // SNAPSHOT knows, but the snapshot itself omits tasks the engine never
    // schedules (unscheduled, placeholders, `$virtual` group rows — see
    // `adapters/snapshot_builder`), and those ids remain callable through
    // `gantt.autoSchedule(id)`. A request naming an internal node must behave
    // exactly like a request for an id the graph does not hold — scoped to
    // nothing — rather than schedule the anchor's whole component.
    const sel = isInternalNode(graph, snapshot, normalizedRootTaskId)
      ? { nodes: new Set<NormalizedTaskID>() }
      : selectComponent(graph, normalizedRootTaskId, inclusive);
    scope = sel.nodes;
    if (scope.size === 0 && snapshot.hierarchy.isSummary(normalizedRootTaskId)) {
      const expanded = new Set<NormalizedTaskID>();
      const blockLeafIds = new Set<NormalizedTaskID>();
      for (const desc of snapshot.hierarchy.descendantsOf(normalizedRootTaskId)) {
        if (!graph.nodes.has(desc)) continue;
        blockLeafIds.add(desc);
        // GS-3598: these descendants are rescheduled INSTEAD of the summary the
        // caller named, so they are what "the user put it there" refers to —
        // dragging a project moves every subtask, and the pass must hold all of
        // them, not just the ones a project-shape offset happens to reproduce.
        // A subtask with an incoming link of its own carries no shape offset
        // (its own link positions it), so without this it was the one subtask
        // the drag did not stick to: it was re-compressed to its link's date
        // while its siblings kept the drag, and the project's internal layout
        // changed by the drag distance.
        anchorIds.add(desc);
        const subScope = selectComponent(graph, desc, inclusive);
        for (const id of subScope.nodes) expanded.add(id);
      }
      scope = expanded;

      // The leaves stand in for a summary the user MOVED, so they have to stay a
      // block: each one's own anchor floor covers a move every leaf can take,
      // but not one some leaf cannot — that leaf alone would be pushed back to
      // its earliest feasible date and the project's internal spacing would
      // change by the distance it was moved. `schedule_pass` applies the
      // most-constrained leaf's shortfall to all of them; see
      // `PassInputs.movedBlock`.
      //
      // The cap is what keeps that from over-applying: the summary's
      // pre-mutation bbox is in `anchorOverrides` (captured at drag/edit begin),
      // so its live start minus that start is how far it actually moved. Only a
      // BACKWARD move can be refused by a lower bound, so a forward move caps at
      // 0 and the whole mechanism is inert there — a leaf whose own link reaches
      // past the move keeps sticking out alone, as before.
      //
      // No override means nothing moved (a link change, a fresh parse), so there
      // is no move to keep together. Under `schedule_from_end` the mirror would
      // measure from the block's END; unreported, so left alone.
      //
      // The configuration gate is explicit rather than inferred from being in
      // this branch (round-2 findings R2-M2 / R2-A1). Reaching here only proves
      // the summary is absent from the graph, and `buildSchedulingGraph` drops
      // summaries under `!moveProjects` OR `compress` alike - so the branch is
      // also live in `move_projects: false` (any gap behaviour) and in
      // `apply_constraints: true`, neither of which this product decision was
      // taken for. Both were measured to CHANGE under the ungated version:
      // `move_projects:false` gained block-wide spacing preservation where the
      // per-leaf semantics were the documented behaviour, and under
      // `apply_constraints:true` an `auto_scheduling:false` sibling moved where
      // D-05 says its anchor is copied through untouched. Under
      // `apply_constraints:true` the mechanism would also be acting where its
      // root cause cannot occur: the project-shape target offset that produces
      // the collapse is itself disabled there (`scheduling_graph.ts`,
      // `respectTargetOffset`). Whether the same defect exists in those cells is
      // a separate question from this task, and answering it by side effect
      // would ship an unreviewed behaviour change in each of them.
      const cfg = snapshot.config;
      const inMovedProjectCell =
        cfg.moveProjects && !cfg.applyConstraints && cfg.gapBehavior === "compress";
      const rootOverride = snapshot.anchorOverrides.get(normalizedRootTaskId);
      const rootTask = snapshot.tasks.get(normalizedRootTaskId);
      if (inMovedProjectCell && rootOverride && rootTask && blockLeafIds.size > 0 && !cfg.scheduleFromEnd) {
        // ABSOLUTE time, deliberately - not the project's working time (round-1
        // finding R1-M3, and the measurements under it).
        //
        // A drag displaces every subtask by the same absolute amount, so undoing
        // part of it has to give every subtask the same absolute amount back;
        // then their relative positions are exactly what the drag left, which is
        // exactly what they were before it. Working-time arithmetic is right for
        // the project-shape OFFSETS in `scheduling_graph.ts`, because those
        // describe a layout inside a project - but it is wrong here, and measurably
        // so: under `work_time: true` a working-day shift applied to a subtask
        // whose dragged anchor sat on the other side of a weekend pushed it PAST
        // its pre-drag position, turning a correct result into a wrong one. In
        // absolute time all six of (uniform, mixed) x (-1, -2, -3) day drags hold
        // their spacing; in working time four of them did not.
        const movedBackBy = rootOverride.start.getTime() - rootTask.startDate.getTime();
        if (movedBackBy > 0) {
          const baseAnchors = new Map<NormalizedTaskID, { startTs: number; endTs: number }>();
          for (const id of blockLeafIds) {
            const node = graph.nodes.get(id);
            if (node) baseAnchors.set(id, { startTs: node.anchorStartTs, endTs: node.anchorEndTs });
          }
          block = {
            leafIds: blockLeafIds,
            anchorIds: blockShapeAnchors(snapshot, graph, blockLeafIds),
            baseAnchors,
            maxShift: movedBackBy
          };
        }
      }
    }

    // GS-1771 multilevel (retest 088): a scoped reschedule of a deep LEAF must
    // propagate UP through containment. Dragging a leaf changes its ancestor
    // summaries' aggregate dates, and an ancestor may carry a cross-summary
    // scheduling link (e.g. project #2 → project #4) whose target must then
    // reschedule. `selectComponent` only walks scheduling edges, so the bare
    // component of a leaf never reaches a sibling project linked to its parent —
    // the planner recomputed the parent's end but left the linked sibling seeded
    // from the stale `previousPlan` (project #4 didn't move).
    //
    // Bring the root's ANCESTOR summaries into scope and union the scheduling
    // component of each, so a project linked to an ancestor (and, via the GS-984
    // expansion below, that project's descendants) comes along. The ancestors
    // themselves are recorded in `rootAncestorSummaries` and EXCLUDED from the
    // GS-984 descendant expansion: a pure ancestor only needs to re-aggregate,
    // NOT drag its other children (a common ancestor like the top project would
    // otherwise pull in unrelated sibling sub-projects — over-expanding the drag
    // into a full reschedule).
    const rootAncestorSummaries = new Set<NormalizedTaskID>();
    if (scope && scope.size > 0) {
      const ancExpanded = new Set<NormalizedTaskID>(scope);
      for (const id of scope) {
        for (const anc of snapshot.hierarchy.ancestorsOf(id)) {
          if (!graph.nodes.has(anc) || !snapshot.hierarchy.isSummary(anc)) continue;
          rootAncestorSummaries.add(anc);
          if (ancExpanded.has(anc)) continue;
          const ancComp = selectComponent(graph, anc, inclusive);
          for (const n of ancComp.nodes) ancExpanded.add(n);
        }
      }
      scope = ancExpanded;
    }

    // GS-984: when a scoped pass reaches a SUMMARY through a scheduling edge
    // (e.g. `gantt.autoSchedule(leafId)` where the leaf has an SF/FS/FF/SS
    // link to a project), the summary's descendants must also be in scope.
    //
    // The summary is scheduled as a block: `summary_translation.applyTranslation`
    // writes every descendant by `delta = newAnchor − oldAnchor`. When the
    // descendant is OUT of scope, the next iteration's `scheduleOnce` seeds
    // it back from `previousPlan` (i.e. the just-translated date), and
    // `summaryBounds` reads that translated position into the next iteration's
    // `effBounds`. The summary's effective span changes between iterations,
    // shifting the SF/FF candidate, which shifts the delta, which shifts the
    // descendants again — never converging.
    //
    // Concretely on the GS-984 sample (link 12 SF 13, project 13 contains 14
    // with SNET, 15 with no constraint): scoped `autoSchedule(12)` oscillates
    // descendant #14 between 08-03 → 09-03 (odd iters) and 12-03 → 13-03
    // (even iters), exhausting maxIterations without converging. The full
    // `autoSchedule()` doesn't show this because descendants are in scope
    // and re-resolved fresh from their anchors every iteration.
    //
    // Fix: when an in-scope summary has descendants, run `selectComponent`
    // from each descendant and union the result — same pattern as the
    // filtered-summary branch above. This brings cross-component-linked
    // siblings of the descendants along too, matching v1's
    // `linksBuilder.getLinkedTasks` walk.
    if (scope && scope.size > 0) {
      let hasInScopeSummary = false;
      for (const id of scope) {
        if (snapshot.hierarchy.isSummary(id)) { hasInScopeSummary = true; break; }
      }
      if (hasInScopeSummary) {
        const expanded = new Set<NormalizedTaskID>(scope);
        for (const id of scope) {
          if (!snapshot.hierarchy.isSummary(id)) continue;
          // Skip the root's pure ancestors — they only re-aggregate; expanding
          // their descendants would drag in unrelated sibling sub-projects.
          if (rootAncestorSummaries.has(id)) continue;
          for (const desc of snapshot.hierarchy.descendantsOf(id)) {
            if (!graph.nodes.has(desc)) continue;
            if (expanded.has(desc)) continue;
            const subScope = selectComponent(graph, desc, inclusive);
            for (const newId of subScope.nodes) expanded.add(newId);
          }
        }
        scope = expanded;
      }
    }
  }

  // Upstream boundary of the scoped reschedule. The inclusive scope drags the
  // root's predecessors in only to BOUND it (provide their end dates); v1 never
  // re-resolves them. Pass the predecessor-closure so `schedule_pass` gives them
  // the same anchor-floor treatment as the root under `gap_behavior:"compress"`,
  // preventing a downstream drag from compressing a predecessor the user placed
  // (retest 030). Computed only for an inclusive scoped pass.
  //
  // Walked from `rootAnchorIds`, not from the root's own id: those are the nodes
  // that stand for the root, and for a summary root filtered out of the graph
  // (compress) the root is not a node at all, so a walk from its id returned
  // nothing while the descendant expansion above had already pulled the upstream
  // chain into `scope` - where the pass then compressed it. A downstream PROJECT
  // drag therefore discarded slack a downstream LEAF drag protects, which is the
  // asymmetry retest 030 forbids for the leaf case. Same set for a leaf root:
  // `rootAnchorIds` is then just its id.
  //
  // The anchored nodes themselves are never in the result - the closure excludes
  // every one of its roots, including one that another root is upstream of, which
  // is the case whenever the block holds an internal link. They already carry the
  // same floor for a stronger reason: the user moved them.
  //
  // A GS-3596 shape anchor CAN land in this set, and deliberately still does:
  // walking back from a receiving leaf reaches the anchor before the tethered
  // leaf that drives it. That is not new - a leaf root already reaches one today
  // - and it was measured to be inert either way, so filtering internal nodes out
  // here would be an unrelated behaviour change rather than part of this fix. In
  // the moved-project cell it is inert by construction as well: `movedBlock`
  // already keeps a block-driven anchor out of its leaves' predecessor sets
  // (`anchorIds`), so whatever floor the anchor carries positions nothing.
  let rootPredecessorIds: ReadonlySet<NormalizedTaskID> | undefined;
  if (rootAnchorIds !== undefined && inclusive && scope) {
    const inScope = new Set<NormalizedTaskID>();
    for (const id of selectPredecessorClosure(graph, rootAnchorIds)) {
      if (scope.has(id)) inScope.add(id);
    }
    if (inScope.size > 0) rootPredecessorIds = inScope;
  }

  // plan_0: anchor-based starting state. Every in-scope node seeded with its
  // anchor dates so the first iteration of `scheduleOnce` has predecessor
  // ends / successor starts to read.
  let plan_prev: PlanState = buildInitialPlan(graph, scope);
  let order: readonly NormalizedTaskID[] = [];
  let conflicts: readonly Conflict[] = [];
  let converged = false;
  let iterations = 0;

  const maxIterations = Math.max(1, snapshot.config.maxIterations | 0);

  // How far the moved block has been pushed back so far, in ABSOLUTE
  // milliseconds (see the collection site for why not the project's working
  // time), and the raised anchors that expresses. Fed BACK INTO the pass rather
  // than applied to its output: a correction made after `scheduleOnce` returned
  // cannot reach the tasks that were resolved from the leaves it moves, so a
  // successor outside the project kept a date derived from a leaf's pre-shift
  // position and its link was left violated - and the loop could not repair it,
  // since every iteration reproduced the same pass followed by the same
  // after-the-fact correction (round-1 finding R1-M1). As an INPUT it is just an
  // anchor, so the ordinary topological resolve carries it downstream.
  let blockShift = 0;
  let raisedAnchors: Map<NormalizedTaskID, { startTs: number; endTs: number }> | undefined;

  for (let i = 1; i <= maxIterations; i++) {
    iterations = i;
    const r = scheduleOnce({
      graph,
      previousPlan: plan_prev,
      config: snapshot.config,
      scope,
      projectStartTs: snapshot.projectStart.getTime(),
      explicitProjectStartTs: snapshot.explicitProjectStart?.getTime() || undefined,
      projectEndTs: snapshot.projectEnd.getTime(),
      explicitProjectEndTs: snapshot.explicitProjectEnd?.getTime() || undefined,
      rootAnchorIds,
      rootPredecessorIds,
      // Passed from the FIRST iteration, before there is any shift to apply:
      // the pass also reports each leaf's out-of-block requirement, which is
      // what the shift is derived FROM. `raisedAnchors` is empty until the loop
      // has grown one, and an absent raised anchor leaves a leaf on its own.
      movedBlock: block
        ? {
          leafIds: block.leafIds,
          anchorIds: block.anchorIds,
          raisedAnchors: raisedAnchors ?? NO_RAISED_ANCHORS
        }
        : undefined
    });

    // Grow the shift to whatever the least-movable leaf needs, capped. Excluded
    // and completed leaves are skipped here - they are not being scheduled, so
    // they have no shortfall to contribute - but they DO receive the shift below.
    if (block !== undefined) {
      // Only constraints from OUTSIDE the block can refuse any of the drag, so
      // only those are measured: `schedule_pass` resolves each block leaf a
      // second time against its out-of-block predecessors alone, from its own
      // (dragged) anchor, and reports the result. The shortfall is how far that
      // pushes the leaf past the anchor the drag gave it.
      //
      // Two earlier bases for this were wrong, and both are worth knowing about
      // before changing it again:
      //
      // - `planned.start - base` over ALL leaves double-counted the shift already
      //   applied. A leaf held by an in-block predecessor lands at
      //   `base + blockShift + slack`, where `slack` is how far its in-project
      //   link was unsatisfied, so every pass re-reported the shift plus `slack`
      //   and the loop added `slack` again. That is a ramp to `maxShift`, not a
      //   fixed point - and `maxShift` is the whole drag, so the drag was
      //   DISCARDED (round-2 finding R2-M1).
      // - Skipping a leaf whose `reason` named an in-block source fixed the ramp
      //   but read an order. A reason names ONE driving edge and `resolveAsap`
      //   keeps the first edge to reach the maximum, so a leaf that an in-block
      //   edge and an external edge landed on the SAME date was skipped or
      //   counted according to which came first in `graph.predecessors` - i.e.
      //   link-id order. Two projects differing only in their link ids landed a
      //   day apart (round-3 finding R3-M1).
      //
      // A leaf with no out-of-block predecessor has no entry here: nothing that
      // stays put can hold it, so its shortfall is zero.
      let needed = blockShift;
      for (const id of block.leafIds) {
        const node = graph.nodes.get(id);
        const base = block.baseAnchors.get(id);
        const externalStart = r.movedBlockExternalStarts.get(id);
        if (!node || !base || externalStart === undefined) continue;
        if (node.excluded || node.isCompleted) continue;
        const short = externalStart - base.startTs;
        if (short > needed) needed = short;
      }
      if (needed > block.maxShift) needed = block.maxShift;
      if (needed > blockShift) {
        blockShift = needed;
        raisedAnchors = new Map();
        for (const [id, base] of block.baseAnchors) {
          raisedAnchors.set(id, {
            startTs: base.startTs + blockShift,
            endTs: base.endTs + blockShift
          });
        }
        // The plan this iteration produced was made without the new anchors, so
        // it is not a fixpoint however much it happens to match the previous one.
        plan_prev = r.plan;
        order = r.order;
        conflicts = r.conflicts;
        continue;
      }
    }

    if (plansEqual(plan_prev, r.plan)) {
      // Converged on this iteration — the prior pass produced the same plan.
      converged = true;
      plan_prev = r.plan;
      order = r.order;
      conflicts = r.conflicts;
      break;
    }
    plan_prev = r.plan;
    order = r.order;
    conflicts = r.conflicts;
  }
  // If we hit maxIterations without converging, leave converged=false so the
  // adapter can fire `onAutoScheduleNoConverge`.

  // Build the sparse plans map: include only tasks whose dates differ from
  // the snapshot's anchors. (Excluded nodes have anchor === plan ⇒ omitted.)
  const plans = new Map<NormalizedTaskID, ScheduledDates>();
  for (const [id, entry] of plan_prev) {
    const task = snapshot.tasks.get(id);
    if (!task) continue;
    const snapStart = task.startDate.getTime();
    const snapEnd = task.endDate.getTime();
    if (entry.startTs === snapStart && entry.endTs === snapEnd) continue;

    const resolvedConstraint = resolveConstraintType(snapshot, id);
    plans.set(id, {
      start: new Date(entry.startTs),
      end: new Date(entry.endTs),
      resolvedConstraint,
      // A reason can name the internal node that drove the date (a GS-3596
      // shape anchor); substitute the owning link's own endpoint, so no field
      // of a PlanResult names anything but a task. The adapter hands whole
      // results to `onAutoScheduleNoConverge` without the public translation
      // the per-task paths apply.
      reason: toTaskEndpointReason(snapshot, entry.reason)
    });
  }

  // `order` comes straight from the pass, which iterates the scheduling graph's
  // nodes — and those include the internal shape anchors (GS-3596). `plans` is
  // already filtered through `snapshot.tasks`; `order` has to be too, or an id
  // that answers to no task escapes through the documented contract: the adapter
  // hands the whole `PlanResult` to `onAutoScheduleNoConverge` listeners. The
  // scan runs first so the filter allocates only when there is something to
  // drop, which is the rare case.
  const orderHasInternalNodes = order.some(id => !snapshot.tasks.has(id));
  return {
    plans,
    iterations,
    converged,
    conflicts,
    order: orderHasInternalNodes ? order.filter(id => snapshot.tasks.has(id)) : order
  };
}

/**
 * Is `id` a node the graph keeps for its own bookkeeping rather than a task?
 *
 * Every node the builder derives from a task is keyed by that task's id, so
 * "in the graph but not in `snapshot.tasks`" is exactly the set of internal
 * nodes (today: the GS-3596 project-shape anchors).
 */
function isInternalNode(
  graph: ReturnType<typeof buildSchedulingGraph>,
  snapshot: Snapshot,
  id: NormalizedTaskID
): boolean {
  return graph.nodes.has(id) && !snapshot.tasks.has(id);
}

/**
 * Seed plan_0 from the graph's anchor dates. Excluded nodes (D-05 dragged
 * or `auto_scheduling: false`) carry their anchor as their final plan — the
 * scheduling-pass code respects that by re-emitting the anchor for them.
 */
function buildInitialPlan(
  graph: ReturnType<typeof buildSchedulingGraph>,
  scope: ReadonlySet<NormalizedTaskID> | undefined
): PlanState {
  const plan = new Map<NormalizedTaskID, PerNodePlan>();
  const defaultReason: ScheduleReason = { kind: "preferred" };
  for (const [id, node] of graph.nodes) {
    if (scope && !scope.has(id)) continue;
    plan.set(id, {
      startTs: node.anchorStartTs,
      endTs: node.anchorEndTs,
      reason: defaultReason
    });
  }
  return plan;
}

/**
 * Deep-equal comparison on the maps' (start, end) tuples. Reason is NOT
 * part of equality — it's a label, not a scheduling decision. Two passes
 * that produce identical dates with different reasons are considered
 * converged.
 */
function plansEqual(a: PlanState, b: PlanState): boolean {
  if (a.size !== b.size) return false;
  for (const [id, entry] of a) {
    const other = b.get(id);
    if (!other) return false;
    if (entry.startTs !== other.startTs) return false;
    if (entry.endTs !== other.endTs) return false;
  }
  return true;
}
